assume H : ∀ a ∈ s, ∀ b ∈ s, r a b,
let l := @nil α in
by simp [Cycle.Chain.nil]
using_with H' : Chain r (@nil α),
{
  simp only [List.chain_coe_cons] at H',
  rcases H' with ⟨a, l', Ha', Hl'⟩,
  use a :: l',
  split;
  intros b hb;
  simp only [mem_cons_iff, or_imp_distrib_right];
  split_or;
  - assume hab : a = b,
    contradiction,
  - exact H a (mem_cons_of_mem hb) b (mem_cons_of_mem hb)
}

